() => {
  // Find all product cards in the search results
  const items = document.querySelectorAll('[data-component-type="s-search-result"]');
  const results = [];
  items.forEach((item, idx) => {
    if (idx >= 6) return; // only first few
    const titleEl = item.querySelector('h2 a, h2');
    const linkEl = item.querySelector('h2 a');
    const priceEl = item.querySelector('.a-price .a-offscreen');
    const asin = item.getAttribute('data-asin');
    results.push({
      idx,
      asin,
      title: titleEl ? titleEl.textContent.trim() : null,
      href: linkEl ? linkEl.getAttribute('href') : null,
      price: priceEl ? priceEl.textContent.trim() : null,
      isSponsored: !!item.querySelector('[data-component-type="sp-sponsored-result"]') || item.classList.contains('AdHolder')
    });
  });
  return results;
}

() => {
  const items = document.querySelectorAll('div[data-asin]');
  const results = [];
  items.forEach((item) => {
    const asin = item.getAttribute('data-asin');
    if (!asin || asin === '') return;
    const titleEl = item.querySelector('h2');
    const linkEl = item.querySelector('a.a-link-normal.s-no-outline, h2 a');
    const priceEl = item.querySelector('.a-price .a-offscreen, span.a-price span.a-offscreen');
    if (titleEl && priceEl) {
      results.push({
        asin,
        title: titleEl.textContent.trim().substring(0, 200),
        href: linkEl ? linkEl.getAttribute('href') : null,
        price: priceEl.textContent.trim()
      });
    }
  });
  return results.slice(0, 8);
}

() => {
  const items = document.querySelectorAll('div[data-asin]');
  const results = [];
  items.forEach((item) => {
    const asin = item.getAttribute('data-asin');
    if (!asin || asin === '') return;
    const titleEl = item.querySelector('h2');
    const linkEl = item.querySelector('a.a-link-normal.s-no-outline, h2 a, a.s-no-outline');
    const priceEl = item.querySelector('.a-price .a-offscreen, span.a-price span.a-offscreen');
    if (titleEl) {
      results.push({
        asin,
        title: titleEl.textContent.trim().substring(0, 300),
        href: linkEl ? linkEl.getAttribute('href') : null,
        price: priceEl ? priceEl.textContent.trim() : null
      });
    }
  });
  return JSON.stringify(results.slice(0, 10), null, 2);
}

() => {
  // Find product links in the search results grid
  const anchors = document.querySelectorAll('a.a-link-normal.s-no-outline, a.s-line-clamp-4, a.s-line-clamp-3, a.s-line-clamp-2');
  const data = [];
  anchors.forEach(a => {
    const href = a.getAttribute('href');
    const text = a.textContent.trim().substring(0, 100);
    if (href && (href.includes('/dp/') || href.includes('/gp/'))) {
      data.push({href, text});
    }
  });
  // Also try a broader search
  const allAnchors = document.querySelectorAll('a');
  const dpLinks = [];
  allAnchors.forEach(a => {
    const href = a.getAttribute('href') || '';
    if (href.includes('/dp/B0') || href.includes('/gp/product/')) {
      dpLinks.push({href, text: a.textContent.trim().substring(0, 100)});
    }
  });
  return JSON.stringify({anchors: data.slice(0, 20), dpLinks: dpLinks.slice(0, 20)}, null, 2);
}

() => {
  // Find the first product by anchoring on a known title text
  const anchor = __find("Adjustable Electrician Climbing Shoes with Secure Spikes - Professional Non-Slip Foot Buckles")[0];
  if (!anchor) return "Anchor not found";
  // Get the records
  const r = __records(anchor);
  return { count: r.length, structure: __skeleton(r[0], 3) };
}
